"use client";
import Nav from "@/components/Nav";
import { useState, useEffect, useRef } from "react";

const CALC_IMG = "data:image/png;base64,";

function fmt(n) { return Math.round(n).toLocaleString(); }

function NumInput({ label, sub, value, onChange, prefix, suffix, placeholder, warn }) {
  const ref = useRef();
  return (
    <div style={{ marginBottom:20 }}>
      <div style={{ fontSize:13, fontWeight:700, color:"#3a3632", marginBottom:2 }}>{label}</div>
      {sub && <div style={{ fontSize:11, color:"#b8b0a8", marginBottom:8 }}>{sub}</div>}
      <div style={{ display:"flex", alignItems:"center", gap:0, background:"#faf8f4", borderRadius:14, border: warn ? "2px solid #e0a060" : "1px solid #e8e0d4", overflow:"hidden", transition:"border 0.2s" }}>
        {prefix && <span style={{ padding:"12px 0 12px 16px", fontSize:14, color:"#b8b0a8", fontWeight:600, flexShrink:0 }}>{prefix}</span>}
        <input ref={ref} type="text" inputMode="numeric" value={value ? fmt(value) : ""} placeholder={placeholder || "0"}
          onChange={e => { const n = parseInt(e.target.value.replace(/[^0-9]/g,"")); onChange(isNaN(n)?0:n); }}
          style={{ flex:1, border:"none", background:"none", padding:"12px 12px", fontSize:16, fontWeight:700, color:"#3a3632", outline:"none", fontFamily:"inherit", minWidth:0 }}/>
        {suffix && <span style={{ padding:"12px 16px 12px 0", fontSize:13, color:"#b8b0a8", flexShrink:0 }}>{suffix}</span>}
      </div>
      {warn && <div style={{ fontSize:11, color:"#c08040", marginTop:4, fontWeight:600 }}>{warn}</div>}
    </div>
  );
}

function OptionCards({ options, value, onChange }) {
  return (
    <div style={{ display:"flex", gap:10, marginBottom:20 }}>
      {options.map(opt => (
        <div key={opt.id} onClick={() => onChange(opt.id)} style={{
          flex:1, padding:"16px 18px", borderRadius:18, cursor:"pointer",
          border: value === opt.id ? "2px solid #5a8a6a" : "2px solid #e8e0d4",
          background: value === opt.id ? "#eaf5ee" : "#faf8f4",
          transition:"all 0.2s",
        }}>
          <div style={{ fontSize:20, marginBottom:6 }}>{opt.icon}</div>
          <div style={{ fontSize:14, fontWeight:700, color: value === opt.id ? "#3a6a4a" : "#3a3632" }}>{opt.label}</div>
          <div style={{ fontSize:11, color: value === opt.id ? "#5a8a6a" : "#b8b0a8", marginTop:3, lineHeight:1.5 }}>{opt.desc}</div>
        </div>
      ))}
    </div>
  );
}

function Slider({ value, onChange, min, max, step, format, label, sub, color }) {
  const pct = ((value - min) / (max - min)) * 100;
  return (
    <div style={{ marginBottom:24 }}>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-end", marginBottom:10 }}>
        <div>
          <div style={{ fontSize:13, fontWeight:700, color:"#3a3632" }}>{label}</div>
          {sub && <div style={{ fontSize:11, color:"#b8b0a8", marginTop:2 }}>{sub}</div>}
        </div>
        <div style={{ fontSize:24, fontWeight:900, color: color || "#3a3632" }}>{format(value)}</div>
      </div>
      <div style={{ position:"relative", height:6, background:"#e8e0d4", borderRadius:3 }}>
        <div style={{ position:"absolute", left:0, top:0, height:"100%", width:`${pct}%`, background: color || "#5a8a6a", borderRadius:3, transition:"width 0.1s" }}/>
        <input type="range" min={min} max={max} step={step} value={value}
          onChange={e => onChange(Number(e.target.value))}
          style={{ position:"absolute", top:-8, left:0, width:"100%", height:22, opacity:0, cursor:"pointer" }}/>
        <div style={{ position:"absolute", top:-5, left:`${pct}%`, transform:"translateX(-50%)", width:16, height:16, borderRadius:8, background:"#fff", border:`3px solid ${color || "#5a8a6a"}`, boxShadow:`0 2px 8px ${color || "#5a8a6a"}30`, transition:"left 0.1s" }}/>
      </div>
      <div style={{ display:"flex", justifyContent:"space-between", marginTop:6, fontSize:10, color:"#c8c0b8" }}>
        <span>{format(min)}</span><span>{format(max)}</span>
      </div>
    </div>
  );
}

function StepDot({ step, current, label }) {
  const done = current > step;
  const active = current === step;
  return (
    <div style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:6, flex:1, position:"relative", zIndex:1 }}>
      <div style={{
        width:36, height:36, borderRadius:18,
        background: done ? "#5a8a6a" : active ? "#3a3632" : "#e8e0d4",
        color: done || active ? "#fff" : "#b8b0a8",
        display:"flex", alignItems:"center", justifyContent:"center",
        fontSize:13, fontWeight:800, transition:"all 0.3s",
        border: done || active ? "none" : "3px solid #f8f4ec",
        boxShadow: "0 0 0 3px #f8f4ec",
      }}>{done ? "✓" : step}</div>
      <span style={{ fontSize:10, fontWeight: active ? 700 : 500, color: active ? "#3a3632" : "#b8b0a8" }}>{label}</span>
    </div>
  );
}

function ResultBar({ label, value, max, color, suffix }) {
  const [w, setW] = useState(0);
  useEffect(() => { setTimeout(() => setW(Math.min((value / max) * 100, 100)), 100); }, [value, max]);
  return (
    <div style={{ marginBottom:14 }}>
      <div style={{ display:"flex", justifyContent:"space-between", marginBottom:5 }}>
        <span style={{ fontSize:13, fontWeight:600, color:"#6a6258" }}>{label}</span>
        <span style={{ fontSize:15, fontWeight:800, color }}>${fmt(value)}</span>
      </div>
      <div style={{ height:8, background:"#f0ebe0", borderRadius:4, overflow:"hidden" }}>
        <div style={{ height:"100%", width:`${w}%`, background: color, borderRadius:4, transition:"width 0.8s cubic-bezier(0.4,0,0.2,1)" }}/>
      </div>
    </div>
  );
}

export default function AffordabilityCalc() {
  const [step, setStep] = useState(1);

  // Step 1: 收入
  const [mainIncome, setMainIncome] = useState(55000);
  const [sideIncome, setSideIncome] = useState(0);
  const [extraAnnual, setExtraAnnual] = useState(60000);
  const [incomeType, setIncomeType] = useState("salary");

  // Step 2: 生活與存款
  const [savings, setSavings] = useState(2000000);
  const [monthlyExpense, setMonthlyExpense] = useState(8000);
  const [monthlySave, setMonthlySave] = useState(15000);
  const [firstBuy, setFirstBuy] = useState(true);

  // Step 3: 期望
  const [loanYears, setLoanYears] = useState(30);
  const [comfortLevel, setComfortLevel] = useState("balanced");

  // Derived
  const totalMonthly = mainIncome + sideIncome;
  const yearlyIncome = totalMonthly * 12 + extraAnnual;
  const rate = firstBuy ? 0.0203 : 0.0215;
  const monthlyRate = rate / 12;
  const totalMonths = loanYears * 12;
  const ratioMap = { safe: 0.28, balanced: 0.33, aggressive: 0.38 };
  const ratio = ratioMap[comfortLevel] || 0.33;
  const maxMonthly = (totalMonthly - monthlyExpense) * ratio / (1 - ratio) < totalMonthly * 0.4
    ? Math.min(totalMonthly * ratio, totalMonthly - monthlyExpense - monthlySave)
    : totalMonthly * ratio;
  const safeMaxMonthly = Math.max(Math.min(totalMonthly * ratio, totalMonthly - monthlyExpense - 5000), 0);
  const loanAmount = safeMaxMonthly > 0 ? safeMaxMonthly * (1 - Math.pow(1 + monthlyRate, -totalMonths)) / monthlyRate : 0;
  const loanPercent = firstBuy ? 0.8 : 0.7;
  const maxPrice = loanAmount / loanPercent;
  const downPayment = maxPrice * (1 - loanPercent);
  const tax = maxPrice * 0.06 * 0.4;
  const agentFee = maxPrice * 0.01;
  const otherFees = 75000;
  const totalNeeded = downPayment + tax + agentFee + otherFees;
  const savingsGap = totalNeeded - savings;
  const remainAfterAll = totalMonthly - monthlyExpense - safeMaxMonthly;
  const healthy = remainAfterAll > totalMonthly * 0.25;
  const monthsToGoal = savingsGap > 0 ? Math.ceil(savingsGap / Math.max(monthlySave, 1)) : 0;

  // 每坪估算 (用台北平均做參考)
  const estimatedPingPrice = 50; // 萬/坪
  const estimatedPing = maxPrice > 0 ? Math.round(maxPrice / 10000 / estimatedPingPrice) : 0;

  return (
    <div style={{ background:"#f8f4ec", minHeight:"100vh", fontFamily:"'Noto Sans TC','Nunito',sans-serif" }}>
      <Nav />
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Nunito:wght@400;500;600;700;800;900&family=Noto+Sans+TC:wght@300;400;500;700;800;900&display=swap');
        @keyframes su{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
        *{box-sizing:border-box;margin:0;padding:0}::-webkit-scrollbar{width:0;height:0}
        input::placeholder{color:#c8c0b8}
        input[type=range]{-webkit-appearance:none;appearance:none}
      `}</style>

      <div style={{ maxWidth:720, margin:"0 auto", padding:"0 28px 80px" }}>

        {/* HEADER */}
        <div style={{ display:"flex", alignItems:"center", gap:28, padding:"32px 0 28px" }}>
          <img src={CALC_IMG} alt="" style={{ width:110, height:110, objectFit:"contain", flexShrink:0 }}/>
          <div>
            <div style={{ fontSize:12, fontWeight:700, color:"#5a8a6a", letterSpacing:3, marginBottom:6 }}>STEP 1 工具</div>
            <h1 style={{ fontSize:28, fontWeight:900, color:"#3a3632", letterSpacing:2, marginBottom:6 }}>我，買得起嗎？</h1>
            <p style={{ fontSize:14, color:"#a8a098", lineHeight:1.7 }}>填入真實數字，我們幫你算出最舒服的購屋方案。<br/>不灌水、不畫餅，讓你心裡有底再出發。</p>
          </div>
        </div>

        {/* PROGRESS */}
        <div style={{ display:"flex", alignItems:"flex-start", gap:0, marginBottom:36, position:"relative" }}>
          <div style={{ position:"absolute", top:17, left:"16%", right:"16%", height:2, background:"#e8e0d4", zIndex:0 }}>
            <div style={{ height:"100%", width: step===1?"0%":step===2?"50%":"100%", background:"#5a8a6a", transition:"width 0.4s" }}/>
          </div>
          <StepDot step={1} current={step} label="我的收入"/>
          <StepDot step={2} current={step} label="生活與存款"/>
          <StepDot step={3} current={step} label="我的方案"/>
        </div>

        {/* ═══ STEP 1: 收入 ═══ */}
        {step === 1 && (
          <div style={{ animation:"su 0.35s ease" }}>

            <div style={{ background:"#fff", borderRadius:24, padding:"32px 36px", boxShadow:"0 2px 10px rgba(80,70,50,0.03)", marginBottom:16 }}>
              <div style={{ fontSize:18, fontWeight:800, color:"#3a3632", marginBottom:4 }}>你的收入來源</div>
              <div style={{ fontSize:12, color:"#a8a098", marginBottom:24 }}>不只看薪水，所有穩定進帳都算數</div>

              <div style={{ fontSize:12, fontWeight:700, color:"#8a8278", letterSpacing:2, marginBottom:10 }}>你的工作型態</div>
              <OptionCards value={incomeType} onChange={setIncomeType} options={[
                { id:"salary", icon:"💼", label:"上班族", desc:"每月有固定薪資入帳" },
                { id:"freelance", icon:"💻", label:"自由工作者", desc:"接案或經營自己的事業" },
                { id:"both", icon:"🌙", label:"正職 + 副業", desc:"白天上班、下班後有額外收入" },
              ]}/>

              <NumInput label="每月主要收入" sub="稅前固定薪資，或自由工作者的月平均收入" value={mainIncome} onChange={setMainIncome} prefix="$" suffix="/ 月" placeholder="例如 55,000"/>

              {(incomeType === "both" || incomeType === "freelance") && (
                <NumInput label={incomeType === "both" ? "每月副業 / 兼差收入" : "其他接案收入"} sub="平均每月額外進帳，不穩定的話填保守一點" value={sideIncome} onChange={setSideIncome} prefix="$" suffix="/ 月" placeholder="例如 10,000"/>
              )}

              <NumInput label="一年中的額外收入"
                sub="年終、三節獎金、績效獎金、投資收益、退稅⋯⋯不管名目，一年加起來大概多少就好"
                value={extraAnnual} onChange={setExtraAnnual} prefix="$" suffix="/ 年" placeholder="例如 60,000"/>
            </div>

            {/* live preview */}
            <div style={{ background:"#f0ebe0", borderRadius:20, padding:"18px 24px", marginBottom:20, display:"flex", justifyContent:"space-between", alignItems:"center" }}>
              <div>
                <div style={{ fontSize:12, color:"#8a8278" }}>你的估算年收入</div>
                <div style={{ fontSize:11, color:"#b8b0a8", marginTop:2 }}>（每月 ${fmt(totalMonthly)} × 12）+ 額外 ${fmt(extraAnnual)}</div>
              </div>
              <div style={{ fontSize:28, fontWeight:900, color:"#3a3632" }}>${fmt(yearlyIncome)}</div>
            </div>

            <button onClick={() => setStep(2)} style={{ width:"100%", padding:"16px 0", borderRadius:20, border:"none", background:"#3a3632", color:"#f8f4ec", fontSize:15, fontWeight:700, cursor:"pointer", fontFamily:"inherit", letterSpacing:1, boxShadow:"0 6px 20px rgba(58,54,50,0.15)" }}>下一步 →</button>
          </div>
        )}

        {/* ═══ STEP 2: 生活與存款 ═══ */}
        {step === 2 && (
          <div style={{ animation:"su 0.35s ease" }}>

            <div style={{ background:"#fff", borderRadius:24, padding:"32px 36px", boxShadow:"0 2px 10px rgba(80,70,50,0.03)", marginBottom:16 }}>
              <div style={{ fontSize:18, fontWeight:800, color:"#3a3632", marginBottom:4 }}>你的生活與存款</div>
              <div style={{ fontSize:12, color:"#a8a098", marginBottom:24 }}>我們想確保你買了房之後，還能好好生活</div>

              <NumInput label="目前手上的存款" sub="所有可動用的錢（定存、活存、投資可變現的部分）" value={savings} onChange={setSavings} prefix="$" placeholder="例如 2,000,000"/>

              <NumInput label="每月固定支出" sub="房租、車貸、學貸、保險、孝親費⋯⋯不含生活費" value={monthlyExpense} onChange={setMonthlyExpense} prefix="$" suffix="/ 月" placeholder="例如 8,000"
                warn={monthlyExpense > totalMonthly * 0.5 ? "固定支出超過收入一半了，買房壓力會比較大" : null}/>

              <NumInput label="每月預計存多少" sub="買房前你想維持的儲蓄習慣，也可以是 0" value={monthlySave} onChange={setMonthlySave} prefix="$" suffix="/ 月" placeholder="例如 15,000"/>

              <div style={{ fontSize:12, fontWeight:700, color:"#8a8278", letterSpacing:2, marginBottom:10, marginTop:8 }}>你是首購族嗎？</div>
              <OptionCards value={firstBuy ? "yes" : "no"} onChange={v => setFirstBuy(v === "yes")} options={[
                { id:"yes", icon:"🏠", label:"是，第一間房", desc:"可享新青安優惠利率 2.03%" },
                { id:"no", icon:"🏢", label:"不是", desc:"已有房產，適用一般利率" },
              ]}/>
            </div>

            {/* 你買房之後的生活 preview */}
            <div style={{ background:"#eaf5ee", borderRadius:20, padding:"18px 24px", marginBottom:20 }}>
              <div style={{ fontSize:13, fontWeight:700, color:"#3a6a4a", marginBottom:8 }}>💡 每月資金流預覽</div>
              <div style={{ display:"flex", gap:16 }}>
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:11, color:"#5a8a6a" }}>月收入</div>
                  <div style={{ fontSize:16, fontWeight:800, color:"#3a3632" }}>${fmt(totalMonthly)}</div>
                </div>
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:11, color:"#5a8a6a" }}>固定支出</div>
                  <div style={{ fontSize:16, fontWeight:800, color:"#c07050" }}>-${fmt(monthlyExpense)}</div>
                </div>
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:11, color:"#5a8a6a" }}>可分配</div>
                  <div style={{ fontSize:16, fontWeight:800, color:"#5a8a6a" }}>${fmt(totalMonthly - monthlyExpense)}</div>
                </div>
              </div>
            </div>

            <div style={{ display:"flex", gap:12 }}>
              <button onClick={() => setStep(1)} style={{ flex:1, padding:"16px 0", borderRadius:20, border:"2px solid #d4c8b0", background:"transparent", color:"#6a6258", fontSize:15, fontWeight:700, cursor:"pointer", fontFamily:"inherit" }}>← 上一步</button>
              <button onClick={() => setStep(3)} style={{ flex:2, padding:"16px 0", borderRadius:20, border:"none", background:"#5a8a6a", color:"#fff", fontSize:15, fontWeight:700, cursor:"pointer", fontFamily:"inherit", letterSpacing:1, boxShadow:"0 6px 20px rgba(90,138,106,0.2)" }}>看看我的方案 ✨</button>
            </div>
          </div>
        )}

        {/* ═══ STEP 3: 結果 ═══ */}
        {step === 3 && (
          <div style={{ animation:"su 0.4s ease" }}>

            {/* Comfort level selector */}
            <div style={{ background:"#fff", borderRadius:24, padding:"28px 32px", marginBottom:20, boxShadow:"0 2px 10px rgba(80,70,50,0.03)" }}>
              <div style={{ fontSize:16, fontWeight:800, color:"#3a3632", marginBottom:4 }}>選一個你的購屋步調</div>
              <div style={{ fontSize:12, color:"#a8a098", marginBottom:16 }}>不同步調，不同生活品質。拉拉看，數字會即時變</div>
              <OptionCards value={comfortLevel} onChange={setComfortLevel} options={[
                { id:"safe", icon:"🛋", label:"穩穩來", desc:"月繳佔收入 28%，生活不受影響" },
                { id:"balanced", icon:"⚖️", label:"剛剛好", desc:"月繳佔收入 33%，稍微省一點" },
                { id:"aggressive", icon:"🚀", label:"拚一點", desc:"月繳佔收入 38%，需要縮減開銷" },
              ]}/>
              <Slider label="貸款年限" value={loanYears} onChange={setLoanYears} min={20} max={40} step={5} format={v => `${v} 年`} color="#7a8ea0"/>
            </div>

            {/* Hero result */}
            <div style={{ background:"linear-gradient(135deg, #5a8a6a, #4a7a5a)", borderRadius:28, padding:"36px 40px", marginBottom:20, position:"relative", overflow:"hidden" }}>
              <div style={{ position:"absolute", top:-30, right:-30, width:150, height:150, borderRadius:"50%", background:"rgba(255,255,255,0.06)" }}/>
              <div style={{ position:"relative", zIndex:1, color:"#fff" }}>
                <div style={{ fontSize:13, color:"rgba(255,255,255,0.5)", marginBottom:8 }}>
                  {comfortLevel === "safe" ? "用最輕鬆的步調，" : comfortLevel === "balanced" ? "用剛剛好的步調，" : "稍微拚一下，"}你可以負擔的房屋大約是
                </div>
                <div style={{ fontSize:48, fontWeight:900, letterSpacing:2 }}>${fmt(Math.round(maxPrice / 10000))} <span style={{ fontSize:18, fontWeight:500 }}>萬</span></div>
                <div style={{ fontSize:13, color:"rgba(255,255,255,0.45)", marginTop:4 }}>
                  {maxPrice > 0 ? `以北市均價換算，約可買 ${estimatedPing} 坪左右的空間` : "先調整上方的數字看看"}
                </div>
                <div style={{ marginTop:20, display:"flex", gap:24, flexWrap:"wrap" }}>
                  <div><div style={{ fontSize:11, color:"rgba(255,255,255,0.4)" }}>每月房貸</div><div style={{ fontSize:20, fontWeight:800 }}>${fmt(safeMaxMonthly)}</div></div>
                  <div style={{ width:1, background:"rgba(255,255,255,0.15)" }}/>
                  <div><div style={{ fontSize:11, color:"rgba(255,255,255,0.4)" }}>需要自備</div><div style={{ fontSize:20, fontWeight:800 }}>${fmt(downPayment)}</div></div>
                  <div style={{ width:1, background:"rgba(255,255,255,0.15)" }}/>
                  <div><div style={{ fontSize:11, color:"rgba(255,255,255,0.4)" }}>利率</div><div style={{ fontSize:20, fontWeight:800 }}>{(rate * 100).toFixed(2)}%</div></div>
                  <div style={{ width:1, background:"rgba(255,255,255,0.15)" }}/>
                  <div><div style={{ fontSize:11, color:"rgba(255,255,255,0.4)" }}>貸款年限</div><div style={{ fontSize:20, fontWeight:800 }}>{loanYears} 年</div></div>
                </div>
              </div>
            </div>

            {/* Monthly life after buying */}
            <div style={{ background:"#fff", borderRadius:24, padding:"28px 32px", marginBottom:20, boxShadow:"0 2px 10px rgba(80,70,50,0.03)" }}>
              <div style={{ fontSize:18, fontWeight:800, color:"#3a3632", marginBottom:4 }}>買了房之後，你的每月生活</div>
              <div style={{ fontSize:12, color:"#a8a098", marginBottom:20 }}>確保繳完房貸還能好好過日子</div>
              <ResultBar label="月收入" value={totalMonthly} max={totalMonthly} color="#5a8a6a"/>
              <ResultBar label="固定支出" value={monthlyExpense} max={totalMonthly} color="#a8a098"/>
              <ResultBar label="房貸月繳" value={safeMaxMonthly} max={totalMonthly} color="#c0903a"/>
              <ResultBar label="剩餘可用" value={Math.max(remainAfterAll, 0)} max={totalMonthly} color={healthy ? "#5a8a6a" : "#c07050"}/>
              <div style={{
                background: healthy ? "#eaf5ee" : "#fef0e8", borderRadius:16, padding:"14px 20px",
                display:"flex", alignItems:"center", gap:10, marginTop:8,
              }}>
                <span style={{ fontSize:24 }}>{healthy ? "😊" : "😅"}</span>
                <div style={{ fontSize:13, fontWeight:600, color: healthy ? "#3a6a4a" : "#a06040", lineHeight:1.7 }}>
                  {healthy
                    ? `每月還有 $${fmt(remainAfterAll)} 可以自由運用（吃飯、娛樂、存錢），佔收入 ${Math.round((remainAfterAll / totalMonthly) * 100)}%，生活品質不太會受影響。`
                    : `每月只剩 $${fmt(Math.max(remainAfterAll, 0))}，生活會比較緊。建議切換到「穩穩來」模式，或降低預算。`
                  }
                </div>
              </div>
            </div>

            {/* Total cost */}
            <div style={{ background:"#fff", borderRadius:24, padding:"28px 32px", marginBottom:20, boxShadow:"0 2px 10px rgba(80,70,50,0.03)" }}>
              <div style={{ fontSize:18, fontWeight:800, color:"#3a3632", marginBottom:4 }}>你需要準備的總金額</div>
              <div style={{ fontSize:12, color:"#a8a098", marginBottom:20 }}>不只是頭期款，這些隱形費用別忘了</div>
              {[
                { label: "頭期款", val: downPayment, note: `房價的 ${Math.round((1 - loanPercent) * 100)}%` },
                { label: "契稅（概估）", val: tax, note: "房屋評定現值 × 6%" },
                { label: "仲介費（概估）", val: agentFee, note: "成交價 × 1%" },
                { label: "代書 + 規費 + 印花", val: otherFees, note: "約 $75,000" },
              ].map((item, i) => (
                <div key={i} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", padding:"10px 0", borderBottom: i < 3 ? "1px solid #f0ebe0" : "none" }}>
                  <div>
                    <div style={{ fontSize:13, fontWeight:600, color:"#3a3632" }}>{item.label}</div>
                    <div style={{ fontSize:11, color:"#b8b0a8" }}>{item.note}</div>
                  </div>
                  <span style={{ fontSize:15, fontWeight:800, color:"#3a3632" }}>${fmt(item.val)}</span>
                </div>
              ))}
              <div style={{ display:"flex", justifyContent:"space-between", padding:"14px 0 0", borderTop:"2px solid #e8e0d4", marginTop:8 }}>
                <span style={{ fontSize:14, fontWeight:800, color:"#3a3632" }}>合計需準備</span>
                <span style={{ fontSize:22, fontWeight:900, color:"#c0903a" }}>${fmt(totalNeeded)}</span>
              </div>
            </div>

            {/* Savings gap */}
            <div style={{ background:"#fff", borderRadius:24, padding:"28px 32px", marginBottom:20, boxShadow:"0 2px 10px rgba(80,70,50,0.03)" }}>
              {savingsGap > 0 ? (
                <>
                  <div style={{ fontSize:18, fontWeight:800, color:"#3a3632", marginBottom:16 }}>
                    你的存款還差一點點 💪
                  </div>
                  <div style={{ display:"flex", gap:16, marginBottom:20 }}>
                    <div style={{ flex:1, background:"#f8f4ec", borderRadius:16, padding:"16px 20px", textAlign:"center" }}>
                      <div style={{ fontSize:11, color:"#a8a098" }}>目前存款</div>
                      <div style={{ fontSize:20, fontWeight:800, color:"#3a3632" }}>${fmt(savings)}</div>
                    </div>
                    <div style={{ flex:1, background:"#fef6e8", borderRadius:16, padding:"16px 20px", textAlign:"center" }}>
                      <div style={{ fontSize:11, color:"#a8a098" }}>還需要</div>
                      <div style={{ fontSize:20, fontWeight:800, color:"#c0903a" }}>${fmt(savingsGap)}</div>
                    </div>
                  </div>
                  <div style={{ background:"#f8f4ec", borderRadius:16, padding:"18px 22px" }}>
                    <div style={{ fontSize:14, fontWeight:700, color:"#3a3632", marginBottom:6 }}>
                      {monthlySave > 0
                        ? `如果每月存 $${fmt(monthlySave)}，大約 ${monthsToGoal} 個月後就夠了`
                        : "填入每月預計存款金額，我們幫你算要多久"
                      }
                    </div>
                    {monthlySave > 0 && monthsToGoal > 0 && (
                      <div style={{ fontSize:13, color:"#8a8278", lineHeight:1.7 }}>
                        也就是大約 <strong>{Math.floor(monthsToGoal / 12)} 年 {monthsToGoal % 12} 個月</strong>後。
                        {monthsToGoal <= 24 && " 其實沒有想像中那麼遠 🌟"}
                        {monthsToGoal > 24 && monthsToGoal <= 48 && " 持續存，目標一定會到 🎯"}
                        {monthsToGoal > 48 && " 如果想加速，可以試試「穩穩來」模式降低頭期款門檻。"}
                      </div>
                    )}
                  </div>
                </>
              ) : (
                <div style={{ textAlign:"center" }}>
                  <div style={{ fontSize:36, marginBottom:12 }}>🎉</div>
                  <div style={{ fontSize:20, fontWeight:800, color:"#3a3632", marginBottom:8 }}>你的存款已經夠了！</div>
                  <div style={{ fontSize:14, color:"#5a8a6a", fontWeight:600 }}>
                    扣除所有費用後，還有 ${fmt(-savingsGap)} 的餘裕
                  </div>
                  <div style={{ fontSize:12, color:"#a8a098", marginTop:6 }}>可以當裝潢預算、搬家基金、或緊急預備金</div>
                </div>
              )}
            </div>

            {/* First buyer bonus */}
            {firstBuy && (
              <div style={{ background:"#eaf5ee", borderRadius:20, padding:"20px 24px", marginBottom:20, display:"flex", alignItems:"center", gap:16 }}>
                <div style={{ fontSize:28 }}>🏦</div>
                <div>
                  <div style={{ fontSize:15, fontWeight:700, color:"#3a6a4a" }}>你符合新青安貸款！</div>
                  <div style={{ fontSize:12, color:"#5a8a6a", marginTop:2, lineHeight:1.6 }}>利率 2.03%、最高 8 成、寬限期 5 年。以上試算已套用優惠利率。</div>
                </div>
              </div>
            )}

            {/* Actions */}
            <div style={{ display:"flex", gap:12, marginBottom:20 }}>
              <button onClick={() => setStep(1)} style={{ flex:1, padding:"16px 0", borderRadius:20, border:"2px solid #d4c8b0", background:"transparent", color:"#6a6258", fontSize:14, fontWeight:700, cursor:"pointer", fontFamily:"inherit" }}>重新算一次</button>
              <button style={{ flex:2, padding:"16px 0", borderRadius:20, border:"none", background:"#3a3632", color:"#f8f4ec", fontSize:14, fontWeight:700, cursor:"pointer", fontFamily:"inherit", letterSpacing:1, boxShadow:"0 6px 20px rgba(58,54,50,0.15)" }}>下一步：找適合我的區域 →</button>
            </div>

            <div style={{ fontSize:11, color:"#c8c0b8", lineHeight:1.8, textAlign:"center", padding:"0 16px" }}>
              本試算僅供參考，實際核貸依各銀行審核為準。利率採用 2026 年 5 月數據。
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
